import json,sys
t=open(sys.argv[1],encoding='utf-8').read()
t=t[t.index('{'):]
d=json.loads(t)
print(list(d.keys()))
for c in d['customers']:
    s=c['services']
    out=[c['customerNo']]
    for k,v in s.items():
        def walk(v,path=''):
            if isinstance(v,dict) and 'http' in v:
                st=v['http']; extra=' delay=%s'%v['delaySeconds'] if 'delaySeconds' in v else ''
                if st!=200 or extra: out.append('%s%s:%s%s'%(k,path,st,extra))
                return
            if isinstance(v,dict):
                for kk,vv in v.items(): walk(vv,path+'/'+str(kk))
        walk(v)
    print(' '.join(out))
