BYE = " Bizi aradığınız için teşekkür ederiz, iyi günler."

PRELUDE = r'''
import json, re, datetime
def _js(v):
    if isinstance(v, str):
        s = v.strip()
        if s[:1] in ('[', '('):
            try:
                return json.loads(s)
            except Exception:
                try:
                    import ast
                    return ast.literal_eval(s)
                except Exception:
                    return v
        if s[:1] == chr(123):
            try:
                return json.loads(s)
            except Exception:
                try:
                    import ast
                    return ast.literal_eval(s)
                except Exception:
                    return v
    return v
def _uf(flat):
    root = dict()
    for k in sorted(flat.keys()):
        parts = [p for p in re.split(r'[.\[\]]+', k) if p != '']
        cur = root
        for p in parts[:-1]:
            nxt = cur.get(p)
            if not isinstance(nxt, dict):
                nxt = dict()
                cur[p] = nxt
            cur = nxt
        if parts:
            cur[parts[-1]] = flat[k]
    def fix(o):
        if isinstance(o, dict):
            o2 = dict((kk, fix(vv)) for kk, vv in o.items())
            if o2 and all(str(kk).isdigit() for kk in o2.keys()):
                return [o2[kk] for kk in sorted(o2.keys(), key=lambda x: int(x))]
            return o2
        return o
    return fix(root)
def body_of(n):
    b = _js(vars.get(n + '_body'))
    if isinstance(b, dict) and b:
        return b
    r = _js(vars.get(n + '_response'))
    if isinstance(r, dict):
        d = _js(r.get('data'))
        if isinstance(d, dict) and d:
            return d
    pre = n + '_response.data.'
    flat = dict((k[len(pre):], v) for k, v in vars.items() if isinstance(k, str) and k.startswith(pre) and v not in (None, ''))
    if flat:
        return _uf(flat)
    return dict()
def http_of(n):
    for k in (n + '_http', n + '_response.status_code', n + '_status_code'):
        v = vars.get(k)
        if v not in (None, ''):
            try:
                return int(float(str(v)))
            except Exception:
                pass
    return 0
def result_of(n):
    b = body_of(n)
    res = _js(b.get('result')) if isinstance(b, dict) else None
    if not isinstance(res, dict):
        res = dict()
    code = str(res.get('code') or res.get('returnCode') or vars.get(n + '_rc') or '')
    data = _js(b.get('data')) if isinstance(b, dict) else None
    if not isinstance(data, dict):
        data = dict()
    h = http_of(n)
    ok = (code == '1') and (h in (0, 200))
    return ok, code, h, data
def clear(n):
    for k in list(vars.keys()):
        if isinstance(k, str) and (k.startswith(n + '_response') or k in (n + '_body', n + '_http', n + '_rc', n + '_status_code')):
            vars[k] = ''
