"""Generates workflow.json for the Freya Bank statement-debt phone agent (built from the case documents)."""
import json
from pathlib import Path

OUT = Path(__file__).resolve().parent / "workflow.json"
BASE = "https://freya-mock-bank.konurozkan1905.workers.dev/voice/v1/"
BYE = " Bizi aradığınız için teşekkür ederiz, iyi günler."

PRELUDE = r'''
import json, re, datetime
def _js(v):
    if isinstance(v, str):
        s = v.strip()
        if s[:1] in ('[', '('):
            try:
                return json.loads(s)
            except Exception:
                try:
                    import ast
                    return ast.literal_eval(s)
                except Exception:
                    return v
        if s[:1] == chr(123):
            try:
                return json.loads(s)
            except Exception:
                try:
                    import ast
                    return ast.literal_eval(s)
                except Exception:
                    return v
    return v
def _uf(flat):
    root = dict()
    for k in sorted(flat.keys()):
        parts = [p for p in re.split(r'[.\[\]]+', k) if p != '']
        cur = root
        for p in parts[:-1]:
            nxt = cur.get(p)
            if not isinstance(nxt, dict):
                nxt = dict()
                cur[p] = nxt
            cur = nxt
        if parts:
            cur[parts[-1]] = flat[k]
    def fix(o):
        if isinstance(o, dict):
            o2 = dict((kk, fix(vv)) for kk, vv in o.items())
            if o2 and all(str(kk).isdigit() for kk in o2.keys()):
                return [o2[kk] for kk in sorted(o2.keys(), key=lambda x: int(x))]
            return o2
        return o
    return fix(root)
def body_of(n):
    b = _js(vars.get(n + '_body'))
    if isinstance(b, dict) and b:
        return b
    r = _js(vars.get(n + '_response'))
    if isinstance(r, dict):
        d = _js(r.get('data'))
        if isinstance(d, dict) and d:
            return d
    pre = n + '_response.data.'
    flat = dict((k[len(pre):], v) for k, v in vars.items() if isinstance(k, str) and k.startswith(pre) and v not in (None, ''))
    if flat:
        return _uf(flat)
    return dict()
def http_of(n):
    for k in (n + '_http', n + '_response.status_code', n + '_status_code'):
        v = vars.get(k)
        if v not in (None, ''):
            try:
                return int(float(str(v)))
            except Exception:
                pass
    return 0
def result_of(n):
    b = body_of(n)
    res = _js(b.get('result')) if isinstance(b, dict) else None
    if not isinstance(res, dict):
        res = dict()
    code = str(res.get('code') or res.get('returnCode') or vars.get(n + '_rc') or '')
    data = _js(b.get('data')) if isinstance(b, dict) else None
    if not isinstance(data, dict):
        data = dict()
    h = http_of(n)
    ok = (code == '1') and (h in (0, 200))
    return ok, code, h, data
def clear(n):
    for k in list(vars.keys()):
        if isinstance(k, str) and (k.startswith(n + '_response') or k in (n + '_body', n + '_http', n + '_rc', n + '_status_code')):
            vars[k] = ''
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else w3(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
def num(x):
    try:
        return float(str(x).replace(',', '.'))
    except Exception:
        return 0.0
def money(x, cur):
    c = int(round(abs(num(x)) * 100))
    main, sub = divmod(c, 100)
    if cur == 'TL':
        if sub:
            return words(main) + ' lira ' + words(sub) + ' kuruş'
        return words(main) + ' Türk Lirası'
    nm = dict(USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    sb = 'peni' if cur == 'GBP' else 'sent'
    if sub:
        return words(main) + ' ' + nm + ' ' + words(sub) + ' ' + sb
    return words(main) + ' ' + nm
def cop(phrase):
    w = phrase.strip().split(' ')[-1]
    low = words(int(w)) if w.isdigit() else w.replace('I', 'ı').replace('İ', 'i').lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    lv = vow[-1] if vow else 'e'
    v = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[lv]
    cons = 't' if low[-1:] in list('fstkçşhp') else 'd'
    sep = "'" if (w[:1].isupper() or w[:1].isdigit()) else ''
    return phrase + sep + cons + v + 'r'
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def dsp(s):
    d = pdate(s)
    if not d:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def today():
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()
def dw(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def norm(s):
    s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
    for a, b in (('ı', 'i'), ('ş', 's'), ('ğ', 'g'), ('ü', 'u'), ('ö', 'o'), ('ç', 'c'), ('â', 'a')):
        s = s.replace(a, b)
    return re.sub(r'[^a-z0-9 ]', ' ', s).strip()
def clean_name(n):
    n = str(n or '').strip()
    low = norm(n)
    bad = ['talimat', 'yok say', 'ignore', 'numara', 'prompt', 'sistem', 'instruction', 'kural']
    if len(n) > 40 or any(b in low for b in bad) or re.search(r'\boku\b', low):
        return ''
    return n
def card_ref(c):
    if c.get('name'):
        return 'sonu ' + dw(c['l4']) + ' ile biten ' + c['name'] + ' kartınız'
    return 'sonu ' + dw(c['l4']) + ' ile biten kartınız'
def cards():
    lst = _js(vars.get('cards_json'))
    return lst if isinstance(lst, list) else []
def elig():
    return [c for c in cards() if c.get('main') == 'y']
def read_list():
    r = _js(vars.get('read_cards'))
    return r if isinstance(r, list) else []
def first_prompt(pref):
    el = elig()
    order = [c for c in el if c['num'] not in read_list()] + [c for c in el if c['num'] in read_list()]
    ex = []
    for c in order:
        lab = c['name'] if c.get('name') else 'sonu ' + dw(c['l4']) + ' ile biten kartım'
        if lab not in ex:
            ex.append(lab)
    q = pref + 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(ex) >= 2:
        q += ' Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    elif ex:
        q += ' Örneğin, ' + ex[0] + ' diyebilirsiniz.'
    return q
def all_names():
    ex = []
    for c in elig():
        lab = c['name'] if c.get('name') else 'sonu ' + dw(c['l4']) + ' ile biten kartınız'
        if lab not in ex:
            ex.append(lab)
    if len(ex) > 1:
        return ', '.join(ex[:-1]) + ' ve ' + ex[-1]
    return ex[0] if ex else ''
def select(c):
    vars['sel_card_number'] = c['num']
    vars['sel_l4'] = c['l4']
    vars['sel_name'] = c.get('name') or ''
    vars['sel_cand'] = '[]'
    vars['sel_tries'] = 0
    clear('fetch_balance')
def offer_text():
    wk = str(vars.get('week_changed')) != 'yes'
    em = str(vars.get('email_state')) == 'yes'
    if wk and em:
        return 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    if wk:
        return 'Hesap kesim tarihinizi değiştirebilirim.'
    if em:
        return 'Ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    return ''
'''

S_START = r'''
try:
    for k in ('card_said', 'digits_said', 'reply', 'week_yesno', 'chosen_week', 'confirm_ans', 'send_ans', 'oos_ans'):
        vars[k] = ''
    vars['sel_tries'] = 0
    vars['week_tries'] = 0
    vars['read_cards'] = '[]'
    vars['sel_cand'] = '[]'
    vars['email_state'] = ''
