    vars['last_no_debt'] = 'no'
    vars['after_email'] = 'offer'
    vars['cards_state'] = 'error'
    clear('fetch_cards')
except Exception:
    pass
'''

S_CARDS = r'''
st = 'error'
try:
    ok, code, h, data = result_of('fetch_cards')
    lst0 = _js(data.get('cards'))
    if ok and isinstance(lst0, list):
        lst = []
        for c in lst0:
            c = _js(c)
            if not isinstance(c, dict):
                continue
            n = str(c.get('cardNumber') or '')
            l4 = str(c.get('cardNumberLast4') or n[-4:])
            main = str(c.get('isMainCard')).strip().lower() not in ('false', '0', 'no', 'n')
            lst.append(dict(num=n, l4=l4, name=clean_name(c.get('productName')), main='y' if main else 'n'))
        vars['cards_json'] = json.dumps(lst, ensure_ascii=False)
        el = [c for c in lst if c['main'] == 'y']
        vars['elig_count'] = len(el)
        if len(el) == 0:
            st = 'nocard'
        elif len(el) == 1:
            select(el[0])
            st = 'one'
        else:
            vars['sel_prompt'] = first_prompt('')
            st = 'multi'
    elif code == 'FB_IVR_CHANNEL_102' or h == 404:
        st = 'nocard'
    clear('fetch_cards')
except Exception:
    st = 'error'
vars['cards_state'] = st
'''

S_MATCH = r'''
st = 'ask'
try:
    lst = cards()
    said = str(vars.get('card_said') or '').strip()
    dg = re.sub(r'\D', '', str(vars.get('digits_said') or ''))
    vars['card_said'] = ''
    vars['digits_said'] = ''
    cand = _js(vars.get('sel_cand'))
    if not isinstance(cand, list) or not cand:
        cand = list(range(len(lst)))
    cand = [i for i in cand if isinstance(i, int) and i < len(lst)] or list(range(len(lst)))
    tries = int(num(vars.get('sel_tries')))
    sn = norm(said)
    STOP = set(['yildiz', 'kart', 'karti', 'kartim', 'kartimi', 'kartimin', 'kartin', 'olan', 'benim', 'icin', 'borcu', 'borcunu', 'kredi', 'evet', 'su', 'bu'])
    def toks(s):
        return [t for t in norm(s).split() if t not in STOP]
    def has(utt, t):
        return any(u == t or u.startswith(t) for u in utt)
    m = None
    kind = ''
    allreq = False
    brand = False
    if dg:
        kind = 'digits'
        if len(dg) >= 12:
            def fok(nm):
                n = re.sub(r'\s', '', nm)
                if n.isdigit():
                    return dg.endswith(n) or n.endswith(dg)
                return dg[:6] == n[:6] and dg[-4:] == n[-4:]
            m = [i for i in range(len(lst)) if fok(lst[i]['num'])]
        elif len(dg) >= 5:
            def tok(nm):
                t = nm[-len(dg):]
                if len(t) < len(dg):
                    return False
                return all(a == '*' or a == b for a, b in zip(t, dg))
            m = [i for i in cand if tok(lst[i]['num'])]
            if not m:
                m = [i for i in range(len(lst)) if tok(lst[i]['num'])]
        elif len(dg) == 4:
            m = [i for i in cand if lst[i]['l4'] == dg]
            if not m:
                m = [i for i in range(len(lst)) if lst[i]['l4'] == dg]
        else:
