S_MATCH = r'''
st = 'ask'
try:
    lst = cards()
    said = str(vars.get('card_said') or '').strip()
    dg = re.sub(r'\D', '', str(vars.get('digits_said') or ''))
    vars['card_said'] = ''
    vars['digits_said'] = ''
    cand = _js(vars.get('sel_cand'))
    if not isinstance(cand, list) or not cand:
        cand = list(range(len(lst)))
    cand = [i for i in cand if isinstance(i, int) and i < len(lst)] or list(range(len(lst)))
    tries = int(num(vars.get('sel_tries')))
    sn = norm(said)
    STOP = set(['yildiz', 'kart', 'karti', 'kartim', 'kartimi', 'kartimin', 'kartin', 'olan', 'benim', 'icin', 'borcu', 'borcunu', 'kredi', 'evet', 'su', 'bu'])
    def toks(s):
        return [t for t in norm(s).split() if t not in STOP]
    def has(utt, t):
        return any(u == t or u.startswith(t) for u in utt)
    m = None
    kind = ''
    allreq = False
    brand = False
    if dg:
        kind = 'digits'
        if len(dg) >= 12:
            def fok(nm):
                n = re.sub(r'\s', '', nm)
                if n.isdigit():
                    return dg.endswith(n) or n.endswith(dg)
                return dg[:6] == n[:6] and dg[-4:] == n[-4:]
            m = [i for i in range(len(lst)) if fok(lst[i]['num'])]
        elif len(dg) >= 5:
            def tok(nm):
                t = nm[-len(dg):]
                if len(t) < len(dg):
                    return False
                return all(a == '*' or a == b for a, b in zip(t, dg))
            m = [i for i in cand if tok(lst[i]['num'])]
            if not m:
                m = [i for i in range(len(lst)) if tok(lst[i]['num'])]
        elif len(dg) == 4:
            m = [i for i in cand if lst[i]['l4'] == dg]
            if not m:
                m = [i for i in range(len(lst)) if lst[i]['l4'] == dg]
        else:
            m = []
    elif sn:
        kind = 'name'
        words_ = sn.split()
        if any(w in words_ for w in ('hepsi', 'hepsinin', 'hepsini', 'butun', 'tum', 'tumu', 'tumunun', 'hepsinden')):
            allreq = True
            m = []
        else:
            utt = toks(sn)
            full = []
            for i, c in enumerate(lst):
                ct = toks(c.get('name') or '')
                if ct and all(has(utt, t) for t in ct):
                    full.append((len(ct), i))
            if full:
                mx = max(f[0] for f in full)
                m = [i for (l, i) in full if l == mx]
            else:
                m = [i for i, c in enumerate(lst) if any(has(utt, t) for t in toks(c.get('name') or ''))]
                if not m and 'yildiz' in sn.split() and not utt:
                    brand = True
                    m = list(range(len(lst)))
    prompt = ''
    if m is None:
        st = 'ask'
    elif allreq:
        tries += 1
        vars['sel_cand'] = '[]'
        prompt = first_prompt('Borç bilgisini her seferinde tek bir kart için verebiliyorum. ')
    elif len(m) == 0:
        tries += 1
        if kind == 'digits':
            prompt = 'Söylediğiniz numarayla eşleşen bir kartınız bulunmuyor. ' + first_prompt('')
        else:
            prompt = 'Bu isimde bir kartınız bulunmuyor. Kartlarınız: ' + all_names() + '. Hangisinin borcunu öğrenmek istersiniz?'
        vars['sel_cand'] = '[]'
    elif len(m) == 1:
        c = lst[m[0]]
        if c.get('main') != 'y':
            tries += 1
            vars['sel_cand'] = '[]'
            prompt = 'Bu kart için ekstre borcu sorgulayabileceğiniz uygun bir kart bulunmuyor. Lütfen başka bir kartınızı seçin. ' + first_prompt('')
        else:
            select(c)
            st = 'selected'
    else:
        if sorted(m) == sorted(cand):
            tries += 1
        names = []
        for i in m:
            nm = lst[i].get('name') or ''
            if nm not in names:
                names.append(nm)
        if kind == 'name' and len(names) > 1 and not brand:
            lab = [n if n else 'isimsiz kartınız' for n in names]
            prompt = 'Bu isimle eşleşen birden fazla kartınız var: ' + ', '.join(lab[:-1]) + ' ve ' + lab[-1] + '. Hangisinin borcunu öğrenmek istersiniz?'
        elif kind == 'name':
            disp = 'Yıldız' if brand else (names[0] or 'Bu')
            prompt = disp + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
        elif len(dg) == 4:
            prompt = 'Son dört hanesi ' + dw(dg) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        else:
            prompt = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
        vars['sel_cand'] = json.dumps(m)
    if st != 'selected':
        vars['sel_tries'] = tries
        if tries >= 3:
            st = 'fail'
        elif prompt:
            vars['sel_prompt'] = prompt
            st = 'ask'
except Exception:
    st = 'ask'
vars['match_state'] = st
'''

