            for cur, key, label in CUR[1:]:
                if owes(cur):
                    b = blocks[cur]
                    s = label + ' borcunuz ' + money(b.get('statementDebt'), cur) + ', kalan toplam borcunuz ' + money(b.get('remainingDebt'), cur) + ', ' + cop('ödenmesi gereken minimum tutar ' + money(b.get('minPayment'), cur)) + '.'
