def code_node(name, src, transitions):
    src = PRELUDE + src
    assert "{{" not in src and "}}" not in src, name
    return {
        "name": name, "node_type": "code", "passthrough": True,
        "passthrough_default_transition": transitions[-1]["target_node"],
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {
            "name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {
                "code": {"type": "string", "default": src},
                "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": transitions,
    }


def eq(var, val, target, desc=None):
    return {"target_node": target, "description": desc or f"{var} is {val}",
            "condition": {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}}


def always(target):
    return {"target_node": target, "description": "always", "condition": {"operator": "always"}}


def setv(var, target, desc):
    return {"target_node": target, "description": desc, "condition": {"logic": "or", "conditions": [
        {"logic": "and", "conditions": [{"variable": var, "operator": "is_set"},
                                         {"variable": var, "operator": "not_equals", "operand": ""}]}]}}


def api_node(name, path, fields, prehook_lines, next_node, on_enter=None, write=False):
    props = {k: {"type": "string", "default": v} for k, v in fields.items()}
    pre = ("try:\n    b = config.get('body')\n    if not isinstance(b, dict):\n        b = dict()\n"
           "    d = b.get('data')\n    if not isinstance(d, dict):\n        d = dict()\n"
           + "".join("    " + ln + "\n" for ln in prehook_lines) +
           "    b['data'] = d\n    b['call'] = dict(ani='', lang='tr')\n    config['body'] = b\n"
           "except Exception:\n    pass\n")
    assert "{{" not in pre
    return {
        "name": name, "node_type": "api_request", "passthrough": True,
        "passthrough_default_transition": next_node,
        "on_enter": on_enter or {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{
            "type": "function", "config": {"timeoutMs": 30000, "maxRetries": 0},
            "function": {"name": name, "handler": "__function__:api_call",
                         "description": f"Bank service {path}.",
                         "parameters": {"type": "object", "properties": {
                             "url": {"type": "string", "default": BASE + path},
                             "method": {"type": "string", "default": "POST"},
                             "headers": {"type": "object", "properties": {
                                 "Content-Type": {"type": "string", "default": "application/json"},
                                 "Accept": {"type": "string", "default": "application/json"}}},
                             "body": {"type": "object", "properties": {
                                 "data": {"type": "object", "properties": props},
                                 "call": {"type": "object", "properties": {
                                     "ani": {"type": "string", "default": ""},
                                     "lang": {"type": "string", "default": "tr"}}}}}}}},
            "pre_process_code": pre,
        }],
        "response_mapping": [
            {"path": "data", "variable": name + "_body"},
            {"path": "status_code", "variable": name + "_http"},
            {"path": "data.result.code", "variable": name + "_rc"},
        ],
        "transitions": [always(next_node)],
    }


def end_node(name, fn, text):
    return {
        "name": name, "node_type": "end_call", "on_enter": {"type": "silent"},
        "disable_inactivity_monitor": True, "transitions": [],
        "terminal": {"type": "function", "function": {
            "name": fn, "handler": "__function__:end_call",
            "parameters": {"type": "object", "properties": {
                "message_mode": {"type": "string", "default": "custom"},
                "spoken_message": {"type": "string", "default": text}}}}},
    }


def conv(name, task, on_enter, extraction, transitions, max_turns, max_target, first_only=False):
    n = {
        "name": name, "node_type": "conversation", "task_message": task,
        "on_enter": on_enter, "extraction_schema": extraction, "transitions": transitions,
        "tools": [], "max_node_turns": max_turns, "max_turn_transition": max_target,
    }
    if first_only:
        n["on_enter_first_entry_only"] = True
    return n


def ex(name, desc, enum=None, conf=0.5):
    e = {"name": name, "type": "string", "description": desc, "min_confidence": conf}
    if enum:
        e["enum_values"] = enum
    return e


