    "You asked: \"{{confirm_text}}\". Only a clear 'evet' (or 'onaylıyorum') is a confirmation. If the answer is hedged "
    "(olur herhalde, sanırım, galiba, belki) or unclear, ask plainly once more: 'Değişikliği onaylıyor musunuz? Lütfen evet "
    "ya da hayır olarak yanıtlayın.' Never say the change is done." + NOTOOL,
    {"type": "tts", "text": "{{confirm_text}}"},
    [ex("confirm_ans", "From the latest message only. yes: an explicit, unhedged yes (evet, evet onaylıyorum, onaylıyorum). "
        "no: refuses or does not want the change. unclear: hedged or vague (olur herhalde, sanırım, galiba, belki, bilmem) or anything else.",
        ["yes", "no", "unclear"], 0.6)],
    [eq("confirm_ans", "yes", "do_change"), eq("confirm_ans", "no", "end_menu")],
    3, "end_fail")
nodes["do_change"] = api_node("do_change", "statement.week.change",
                              {"cardNumber": "{{sel_card_number}}", "newStatementWeek": "{{new_week}}", "statementDay": "{{cur_day}}"},
                              ["d['cardNumber'] = str(vars.get('sel_card_number') or d.get('cardNumber') or '')",
                               "d['newStatementWeek'] = int(float(str(vars.get('new_week'))))",
                               "d['statementDay'] = int(float(str(vars.get('cur_day'))))"],
                              "change_check")
nodes["change_check"] = code_node("change_check", S_CHANGE, [eq("change_state", "ok", "talk"), always("end_week_error")])

ENDS = {
    "end_menu": ("main_menu", "Sizi ana menüye yönlendiriyorum." + BYE),
    "end_nocard": ("no_eligible_card", "Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum." + BYE),
    "end_fail": ("tries_exhausted", "Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum." + BYE),
    "end_error": ("agent_service_error", "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum." + BYE),
    "end_week_error": ("agent_week_service_error", "Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum." + BYE),
    "end_agent": ("agent_requested", "Sizi müşteri temsilcimize aktarıyorum." + BYE),
