    "end_pay": ("agent_payment", "Borç ödeme işleminiz için sizi müşteri temsilcimize aktarıyorum." + BYE),
    "end_dispute": ("agent_dispute", "Bu konuda size müşteri temsilcimiz yardımcı olacak, sizi aktarıyorum." + BYE),
    "end_third": ("ivr_login_third_party", "Güvenlik nedeniyle yalnızca kendi kartlarınızla ilgili bilgi verebiliyor ve işlem yapabiliyorum. Kart sahibinin kendi kimliğini doğrulayabilmesi için sizi ana menüdeki giriş adımına yönlendiriyorum." + BYE),
    "end_lang": ("main_menu_language", "Sizi ana menüye aktarıyorum."),
    "end_oos": ("main_menu_out_of_scope", "Sizi ana menüye aktarıyorum." + BYE),
    "end_silence": ("no_input_hangup", "Sesinizi alamadığım için görüşmeyi sonlandırıyorum."),
    "end_noemail": ("main_menu_no_email", "Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum. Sizi ana menüye yönlendiriyorum." + BYE),
    "end_addr": ("main_menu_email_not_current", "Bu görüşmede e-posta adresinizi değiştiremiyorum, ekstrenizi göndermedim. Sizi ana menüye yönlendiriyorum." + BYE),
    "end_other_addr": ("main_menu_other_address", "Ekstrenizi yalnızca bankamızda kayıtlı e-posta adresinize gönderebiliyorum; başka bir adrese, kağıt ya da kısa mesaj olarak gönderemiyorum. Sizi ana menüye yönlendiriyorum." + BYE),
}
for k, (fn, text) in ENDS.items():
    nodes[k] = end_node(k, fn, text)

END_KEYS = list(ENDS.keys())


def g_pass(name, desc, intent, target, excluded_extra=()):
    return {
        "name": name, "node_type": "conversation", "description": desc,
        "condition": {"operator": "matches_intent", "description": intent},
        "task_message": "Hand the call over." + NOTOOL, "on_enter": {"type": "silent"},
        "passthrough": True, "passthrough_default_transition": target,
        "excluded_nodes": END_KEYS + list(excluded_extra), "tools": [], "extraction_schema": [],
        "transitions": [always(target)],
    }


globals_ = {
    "g_agent": g_pass("g_agent", "Caller asks for a human", "The caller asks to speak to a human, a customer representative, an operator or a person (müşteri temsilcisi, operatör, gerçek biri).", "end_agent"),
    "g_pay": g_pass("g_pay", "Caller wants to pay", "The caller wants to pay their card debt now, or asks how or where they can pay it.", "end_pay"),
    "g_dispute": g_pass("g_dispute", "Debt disputed", "The caller says the debt amount is wrong, disputes a transaction, or says a payment they made is not showing.", "end_dispute"),
    "g_third": g_pass("g_third", "Another person's card", "The caller asks about, or wants a transaction on, a card that belongs to another person (spouse, wife, husband, mother, father, child, friend).", "end_third"),
    "g_lang": g_pass("g_lang", "Not Turkish", "The caller's latest message is written entirely in a language other than Turkish (for example English, German or Arabic).", "end_lang"),
    "g_oos": {
        "name": "g_oos", "node_type": "conversation", "description": "Question outside this step",
