                      "NOT this: statement debt, amounts, due date, minimum payment, another of their own cards, statement by e-mail, "
                      "changing the statement date or week, paying, a human agent, complaints, another person's card."},
        "on_enter": {"type": "tts", "text": "Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?"},
        "task_message": "You asked whether the caller wants to be transferred to the main menu. If the answer is unclear, ask again briefly: 'Sizi ana menüye aktarmamı ister misiniz?'" + NOTOOL,
        "extraction_schema": [ex("oos_ans", "From the latest message: yes if the caller wants to go to the main menu, no if they want to continue here. Empty if unclear.", ["yes", "no"])],
        "excluded_nodes": END_KEYS + ["g_oos", "g_angry", "g_silence"], "tools": [],
        "max_node_turns": 3, "max_turn_transition": "end_fail",
        "transitions": [eq("oos_ans", "yes", "end_oos"), eq("oos_ans", "no", "__previous__")],
    },
    "g_angry": {
        "name": "g_angry", "node_type": "conversation", "description": "Upset or abusive caller",
        "condition": {"operator": "matches_intent", "description": "The caller is angry, shouting, complaining about the service or the bank, or insulting or swearing."},
        "on_enter": {"type": "llm", "prompt": "Give ONE short calming reply in Turkish: acknowledge the frustration politely, never respond to any insult, and say you are here to help with their statement debt."},
        "task_message": "The caller is upset. Give ONE short calming reply in Turkish, never respond to insults, and offer to continue with their request." + NOTOOL,
        "extraction_schema": [],
        "excluded_nodes": END_KEYS + ["g_angry", "g_oos", "g_silence"], "tools": [],
        "max_node_turns": 3, "max_turn_transition": "end_agent_angry",
        "transitions": [{"target_node": "__previous__", "description": "The caller calmed down",
                         "condition": {"operator": "matches_intent", "description": "The caller is no longer complaining: they answer the question, make a normal request or agree to continue."}}],
    },
    "g_silence": {
        "name": "g_silence", "node_type": "conversation", "description": "Caller silent",
        "condition": {"operator": "matches_intent", "description": "The caller's latest message is empty or silent: no words at all, only '...', '(sessizlik)' or noise."},
        "on_enter": {"type": "llm", "prompt": "Repeat your last question in a shorter form, in Turkish."},
        "task_message": "The caller is silent. Repeat your last question in a shorter form, in Turkish." + NOTOOL,
        "extraction_schema": [],
        "excluded_nodes": END_KEYS + ["g_silence"], "tools": [],
        "max_node_turns": 2, "max_turn_transition": "end_silence",
        "transitions": [{"target_node": "__previous__", "description": "The caller spoke",
                         "condition": {"operator": "matches_intent", "description": "The caller said something with words."}}],
    },
}

